/*gen:code:graph_repr*/ const CODE_graph_repr = "#include <cstdio>\n#include <utility>\n#include <vector>\n\nstruct Edge { int u, v; };\n\nint main() {\n    const int n = 8;   // vertices A..H = 0..7\n    std::vector<Edge> edges{{0, 1}, {0, 2}, {1, 3}, {2, 3}, {1, 4}, {3, 4},\n                            {3, 5}, {2, 5}, {4, 6}, {5, 7}, {6, 7}};   // undirected\n    const int m = static_cast<int>(edges.size());\n\n    // 1. Adjacency list: one vector of neighbors per vertex.\n    std::vector<std::vector<int>> adj(n);\n    for (auto [u, v] : edges) { adj[u].push_back(v); adj[v].push_back(u); }\n\n    // 2. Adjacency matrix: n*n flags in ONE contiguous block, row-major.\n    std::vector<unsigned char> mat(n * n, 0);\n    for (auto [u, v] : edges) mat[u * n + v] = mat[v * n + u] = 1;\n\n    // 3. CSR (compressed sparse row): all neighbor lists packed into one array.\n    std::vector<int> offset(n + 1, 0);\n    for (auto [u, v] : edges) { ++offset[u + 1]; ++offset[v + 1]; }   // degrees, shifted by one\n    for (int i = 0; i < n; ++i) offset[i + 1] += offset[i];           // prefix sums\n    std::vector<int> target(2 * m);\n    std::vector<int> fill(offset.begin(), offset.end() - 1);          // next free slot per vertex\n    for (auto [u, v] : edges) { target[fill[u]++] = v; target[fill[v]++] = u; }\n\n    auto name = [](int v) { return static_cast<char>('A' + v); };\n    std::printf(\"neighbors of D:  list\");\n    for (int w : adj[3]) std::printf(\" %c\", name(w));\n    std::printf(\"   csr\");\n    for (int k = offset[3]; k < offset[4]; ++k) std::printf(\" %c\", name(target[k]));\n    std::printf(\"\\nedge D-F? matrix says %d, edge A-H? %d\\n\", mat[3 * n + 5], mat[0 * n + 7]);\n    std::printf(\"offsets:\");\n    for (int x : offset) std::printf(\" %d\", x);\n    std::printf(\"\\nstorage: edge list %d pairs, list/csr %d entries, matrix %d cells\\n\", m, 2 * m, n * n);\n}";
/*gen:out:graph_repr*/ const OUT_graph_repr = "neighbors of D:  list B C E F   csr B C E F\nedge D-F? matrix says 1, edge A-H? 0\noffsets: 0 2 5 8 12 15 18 20 22\nstorage: edge list 11 pairs, list/csr 22 entries, matrix 64 cells";
/*gen:code:bfs_paths*/ const CODE_bfs_paths = "#include <algorithm>\n#include <cstdio>\n#include <queue>\n#include <vector>\n\nstruct BfsResult {\n    std::vector<int> dist;     // -1 = unreachable\n    std::vector<int> parent;   // -1 = none (the source, or unreachable)\n};\n\nBfsResult bfs(const std::vector<std::vector<int>>& adj, int s) {\n    const int n = static_cast<int>(adj.size());\n    BfsResult r{std::vector<int>(n, -1), std::vector<int>(n, -1)};\n    std::queue<int> q;\n    r.dist[s] = 0;\n    q.push(s);\n    while (!q.empty()) {\n        int v = q.front();\n        q.pop();\n        for (int w : adj[v]) {\n            if (r.dist[w] != -1) continue;    // already discovered\n            r.dist[w] = r.dist[v] + 1;        // mark on discovery, not on dequeue\n            r.parent[w] = v;\n            q.push(w);\n        }\n    }\n    return r;\n}\n\n// Walk parent pointers back from t, then reverse: the shortest s-t path.\nstd::vector<int> path_to(const BfsResult& r, int t) {\n    std::vector<int> path;\n    if (r.dist[t] == -1) return path;         // unreachable: empty path\n    for (int v = t; v != -1; v = r.parent[v]) path.push_back(v);\n    std::reverse(path.begin(), path.end());\n    return path;\n}\n\nint main() {\n    std::vector<std::vector<int>> adj{\n        {1, 2}, {0, 3, 4}, {0, 3, 5}, {1, 2, 4, 5},   // A B C D\n        {1, 3, 6}, {2, 3, 7}, {4, 7}, {5, 6}};         // E F G H\n    BfsResult r = bfs(adj, 0);\n    for (int v = 0; v < 8; ++v)\n        std::printf(\"%c: dist %d, parent %c\\n\", 'A' + v, r.dist[v], r.parent[v] < 0 ? '-' : 'A' + r.parent[v]);\n    std::printf(\"shortest A->H:\");\n    for (int v : path_to(r, 7)) std::printf(\" %c\", 'A' + v);\n    std::printf(\"\\n\");\n}";
/*gen:out:bfs_paths*/ const OUT_bfs_paths = "A: dist 0, parent -\nB: dist 1, parent A\nC: dist 1, parent A\nD: dist 2, parent B\nE: dist 2, parent B\nF: dist 2, parent C\nG: dist 3, parent E\nH: dist 3, parent F\nshortest A->H: A C F H";
/*gen:code:dfs_times*/ const CODE_dfs_times = "#include <cstdio>\n#include <stack>\n#include <utility>\n#include <vector>\n\nenum Color { WHITE, GRAY, BLACK };   // unseen, on the recursion stack, finished\n\nstruct Dfs {\n    const std::vector<std::vector<int>>& adj;\n    std::vector<Color> color;\n    std::vector<int> d, f;           // discovery and finish times\n    int time = 0;\n\n    explicit Dfs(const std::vector<std::vector<int>>& g)\n        : adj(g), color(g.size(), WHITE), d(g.size(), 0), f(g.size(), 0) {}\n\n    void visit(int u) {\n        color[u] = GRAY;\n        d[u] = ++time;\n        for (int v : adj[u]) {\n            const char* kind = color[v] == WHITE ? \"tree\"\n                             : color[v] == GRAY  ? \"back\"                  // v is an ancestor still open\n                             : d[u] < d[v]       ? \"forward\" : \"cross\";    // v already finished\n            std::printf(\"  %c->%c %s\\n\", 'A' + u, 'A' + v, kind);\n            if (color[v] == WHITE) visit(v);\n        }\n        color[u] = BLACK;\n        f[u] = ++time;\n    }\n};\n\n// The same traversal without recursion: the stack holds (vertex, index of next neighbor).\nstd::vector<int> finish_times_iterative(const std::vector<std::vector<int>>& adj, int s) {\n    std::vector<int> f(adj.size(), 0);\n    std::vector<bool> seen(adj.size(), false);\n    std::stack<std::pair<int, std::size_t>> st;\n    int time = 0;\n    seen[s] = true; ++time;                              // discover s\n    st.push({s, 0});\n    while (!st.empty()) {\n        auto& [u, i] = st.top();\n        if (i < adj[u].size()) {\n            int v = adj[u][i++];                         // advance u's neighbor cursor\n            if (!seen[v]) { seen[v] = true; ++time; st.push({v, 0}); }   // discover v\n        } else {\n            f[u] = ++time;                               // all neighbors done: finish u\n            st.pop();\n        }\n    }\n    return f;\n}\n\nint main() {\n    //                               A       B    C    D          E    F\n    std::vector<std::vector<int>> adj{{1, 3}, {2}, {0}, {2, 4, 5}, {5}, {}};\n    Dfs dfs(adj);\n    dfs.visit(0);\n    for (int v = 0; v < 6; ++v) std::printf(\"%c: d=%d f=%d\\n\", 'A' + v, dfs.d[v], dfs.f[v]);\n    std::vector<int> f = finish_times_iterative(adj, 0);\n    std::printf(\"iterative finish times:\");\n    for (int x : f) std::printf(\" %d\", x);\n    std::printf(\"\\n\");\n}";
/*gen:out:dfs_times*/ const OUT_dfs_times = "  A->B tree\n  B->C tree\n  C->A back\n  A->D tree\n  D->C cross\n  D->E tree\n  E->F tree\n  D->F forward\nA: d=1 f=12\nB: d=2 f=5\nC: d=3 f=4\nD: d=6 f=11\nE: d=7 f=10\nF: d=8 f=9\niterative finish times: 12 5 4 11 10 9";
/*gen:code:grid_bfs*/ const CODE_grid_bfs = "#include <cstdio>\n#include <queue>\n#include <string>\n#include <vector>\n\n// A grid is a graph you never build: cells are vertices, and the neighbors of\n// (r, c) are computed on the fly from four direction offsets.\nconstexpr int DR[4] = {-1, 1, 0, 0};\nconstexpr int DC[4] = {0, 0, -1, 1};\n\nint main() {\n    std::vector<std::string> map{\n        \"S..#....\",\n        \".#.#.##.\",\n        \".#...#..\",\n        \".####.#.\",\n        \"......#G\"};\n    const int H = static_cast<int>(map.size()), W = static_cast<int>(map[0].size());\n    auto id = [W](int r, int c) { return r * W + c; };      // cell -> vertex number\n\n    std::vector<int> dist(H * W, -1), parent(H * W, -1);\n    std::queue<int> q;\n    dist[id(0, 0)] = 0;\n    q.push(id(0, 0));\n    int goal = -1;\n    while (!q.empty()) {\n        int v = q.front(); q.pop();\n        int r = v / W, c = v % W;                           // vertex -> cell\n        if (map[r][c] == 'G') { goal = v; break; }          // first time G is dequeued = shortest\n        for (int k = 0; k < 4; ++k) {\n            int nr = r + DR[k], nc = c + DC[k];\n            if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;   // off the map\n            if (map[nr][nc] == '#' || dist[id(nr, nc)] != -1) continue;\n            dist[id(nr, nc)] = dist[v] + 1;\n            parent[id(nr, nc)] = v;\n            q.push(id(nr, nc));\n        }\n    }\n    std::printf(\"shortest path: %d steps\\n\", dist[goal]);\n    for (int v = parent[goal]; v != id(0, 0); v = parent[v]) map[v / W][v % W] = '*';\n    for (const auto& row : map) std::printf(\"%s\\n\", row.c_str());\n\n    // Flood fill: label every connected region of open cells (paint-bucket fill).\n    std::vector<std::string> level{\n        \"..#.#.\",\n        \"..#.#.\",\n        \"###.#.\",\n        \"#...#.\",\n        \"#.##..\"};\n    const int h = 5, w = 6;\n    std::vector<int> label(h * w, 0);\n    int regions = 0;\n    for (int s = 0; s < h * w; ++s) {\n        if (level[s / w][s % w] == '#' || label[s]) continue;\n        ++regions;                                          // unvisited open cell: new region\n        std::queue<int> fq;\n        label[s] = regions;\n        fq.push(s);\n        while (!fq.empty()) {\n            int v = fq.front(); fq.pop();\n            for (int k = 0; k < 4; ++k) {\n                int nr = v / w + DR[k], nc = v % w + DC[k];\n                if (nr < 0 || nr >= h || nc < 0 || nc >= w) continue;\n                int u = nr * w + nc;\n                if (level[nr][nc] == '#' || label[u]) continue;\n                label[u] = regions;\n                fq.push(u);\n            }\n        }\n    }\n    std::printf(\"regions: %d\\n\", regions);\n    for (int r = 0; r < h; ++r) {\n        for (int c = 0; c < w; ++c) std::printf(\"%c\", level[r][c] == '#' ? '#' : char('0' + label[r * w + c]));\n        std::printf(\"\\n\");\n    }\n}";
